/*
  Egypt geographic hierarchy seed
  Source: https://github.com/open-admin-data/egypt-administrative-divisions
  Dataset snapshot: 2026-10-12
  Levels: 1=governorate, 2=district/city/markaz/qism, 3=shiyakha
  This script is idempotent: it inserts missing records and refreshes the dataset fields.
  It never deletes existing records.
*/

SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRY
  BEGIN TRANSACTION;

  IF OBJECT_ID(N'dbo.geographic_divisions', N'U') IS NULL
  BEGIN
    CREATE TABLE dbo.geographic_divisions (
      id INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_geographic_divisions PRIMARY KEY,
      source_id VARCHAR(20) NOT NULL,
      parent_source_id VARCHAR(20) NULL,
      parent_id INT NULL,
      division_level TINYINT NOT NULL,
      name_ar NVARCHAR(200) NOT NULL,
      name_en NVARCHAR(200) NOT NULL,
      slug NVARCHAR(255) NULL,
      latitude DECIMAL(9,6) NULL,
      longitude DECIMAL(9,6) NULL,
      created_at DATETIME2(0) NOT NULL CONSTRAINT DF_geographic_divisions_created_at DEFAULT SYSUTCDATETIME(),
      updated_at DATETIME2(0) NOT NULL CONSTRAINT DF_geographic_divisions_updated_at DEFAULT SYSUTCDATETIME(),
      CONSTRAINT UQ_geographic_divisions_source_id UNIQUE (source_id),
      CONSTRAINT CK_geographic_divisions_level CHECK (division_level IN (1, 2, 3)),
      CONSTRAINT FK_geographic_divisions_parent FOREIGN KEY (parent_id) REFERENCES dbo.geographic_divisions(id)
    );

    CREATE INDEX IX_geographic_divisions_parent_id
      ON dbo.geographic_divisions(parent_id, division_level);
  END;

  IF COL_LENGTH(N'dbo.geographic_divisions', N'source_id') IS NULL
     OR COL_LENGTH(N'dbo.geographic_divisions', N'parent_source_id') IS NULL
     OR COL_LENGTH(N'dbo.geographic_divisions', N'parent_id') IS NULL
     OR COL_LENGTH(N'dbo.geographic_divisions', N'division_level') IS NULL
  BEGIN
    THROW 50000, 'dbo.geographic_divisions exists but does not have the required hierarchy schema.', 1;
  END;

  CREATE TABLE #EgyptGeography (
    source_id VARCHAR(20) NOT NULL PRIMARY KEY,
    parent_source_id VARCHAR(20) NULL,
    division_level TINYINT NOT NULL,
    name_ar NVARCHAR(200) NOT NULL,
    name_en NVARCHAR(200) NOT NULL,
    slug NVARCHAR(255) NULL,
    latitude DECIMAL(9,6) NULL,
    longitude DECIMAL(9,6) NULL
  );

