    (N'EG350710', N'EG3507', 3, N'وادى حمص', N'Wadi Homs', N'-eg350710', 29.028, 34.288),
    (N'EG350711', N'EG3507', 3, N'واديصغير', N'Wadi Saghir', N'-eg350711', 28.944, 34.425),
    (N'EG350801', N'EG3508', 3, N'قرية طابا', N'Qaryet Taba', N'-eg350801', 29.513, 34.85);

  IF (SELECT COUNT(*) FROM #EgyptGeography) <> 6108
    THROW 50001, 'The Egypt geography seed is incomplete.', 1;

  IF EXISTS (
    SELECT 1
    FROM #EgyptGeography AS child
    LEFT JOIN #EgyptGeography AS parent ON parent.source_id = child.parent_source_id
    WHERE child.parent_source_id IS NOT NULL AND parent.source_id IS NULL
  )
    THROW 50002, 'The Egypt geography seed contains an unresolved parent.', 1;

  UPDATE target
  SET
    parent_source_id = source.parent_source_id,
    division_level = source.division_level,
    name_ar = source.name_ar,
    name_en = source.name_en,
    slug = source.slug,
    latitude = source.latitude,
    longitude = source.longitude,
    updated_at = SYSUTCDATETIME()
  FROM dbo.geographic_divisions AS target
  INNER JOIN #EgyptGeography AS source ON source.source_id = target.source_id;

  INSERT INTO dbo.geographic_divisions (
    source_id, parent_source_id, parent_id, division_level, name_ar, name_en, slug, latitude, longitude
  )
  SELECT
    source_id, parent_source_id, NULL, division_level, name_ar, name_en, slug, latitude, longitude
  FROM #EgyptGeography AS source
  WHERE NOT EXISTS (
    SELECT 1
    FROM dbo.geographic_divisions AS target
    WHERE target.source_id = source.source_id
  );

  UPDATE child
  SET parent_id = parent.id, updated_at = SYSUTCDATETIME()
  FROM dbo.geographic_divisions AS child
  INNER JOIN dbo.geographic_divisions AS parent ON parent.source_id = child.parent_source_id
  WHERE child.parent_source_id IS NOT NULL
    AND (child.parent_id IS NULL OR child.parent_id <> parent.id);

  UPDATE dbo.geographic_divisions
  SET parent_id = NULL, updated_at = SYSUTCDATETIME()
  WHERE parent_source_id IS NULL AND parent_id IS NOT NULL;

  IF (
    SELECT COUNT(*)
    FROM dbo.geographic_divisions AS target
    INNER JOIN #EgyptGeography AS source ON source.source_id = target.source_id
  ) <> 6108
    THROW 50003, 'Not every seed record was stored.', 1;

  IF EXISTS (
    SELECT 1
    FROM dbo.geographic_divisions AS child
    INNER JOIN #EgyptGeography AS source ON source.source_id = child.source_id
    WHERE child.parent_source_id IS NOT NULL AND child.parent_id IS NULL
  )
    THROW 50004, 'Not every geography parent was resolved.', 1;

  COMMIT TRANSACTION;
END TRY
BEGIN CATCH
  IF XACT_STATE() <> 0
    ROLLBACK TRANSACTION;
  THROW;
END CATCH;

-- Verification query: returns the complete hierarchy with official source identifiers.
SELECT
  parent.source_id AS governorate_source_id,
  parent.name_ar AS governorate_name_ar,
  division.source_id,
  division.division_level,
  division.name_ar,
  division.name_en,
  division.parent_source_id
FROM dbo.geographic_divisions AS division
LEFT JOIN dbo.geographic_divisions AS parent ON parent.id = division.parent_id
ORDER BY division.division_level, division.parent_source_id, division.name_ar;
